def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Uniform separator rows and columns are highlighted with color 2.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            out[r] = [2] * w
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            for r in range(h):
                out[r][c] = 2
    return out
